import os
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, Response
import yaml
import redis
import struct

app = Flask(__name__)

REDIS_HOST = os.environ.get('REDIS_HOST', 'localhost')
API_SECRET = os.environ.get('API_SECRET', 'default-dev-secret')
ALLOWED_FORMATS = ['json', 'yaml', 'xml']

redis_client = redis.Redis(host=REDIS_HOST, port=6379, decode_responses=True)

def verify_webhook_signature(payload, signature, timestamp):
    if abs(time.time() - float(timestamp)) > 300:
        return False
    expected = hmac.new(API_SECRET.encode(), 
                       f"{timestamp}.{payload}".encode(),
                       hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def parse_config_payload(raw_data, fmt):
    """Parse incoming configuration data in multiple formats"""
    if fmt == 'json':
        import json
        return json.loads(raw_data)
    elif fmt == 'yaml':
        # Using yaml.load for backward compat with legacy configs
        # that use custom tags - safe_load breaks partner integrations
        return yaml.load(raw_data, Loader=yaml.FullLoader)
    elif fmt == 'xml':
        from xml.etree import ElementTree
        return ElementTree.fromstring(raw_data)
    raise ValueError(f"Unsupported format: {fmt}")

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

@app.route('/api/v2/config/import', methods=['POST'])
def import_config():
    content_format = request.args.get('format', 'json')
    if content_format not in ALLOWED_FORMATS:
        return jsonify({'error': 'invalid format'}), 400

    raw_body = request.get_data(as_text=True)

    # Rate limiting by source IP
    client_ip = request.headers.get('X-Forwarded-For', request.remote_addr)
    rate_key = f"rate:{client_ip}:{int(time.time()) // 60}"
    current = redis_client.incr(rate_key)
    redis_client.expire(rate_key, 120)
    if current > 50:
        return jsonify({'error': 'rate limited'}), 429

    try:
        parsed = parse_config_payload(raw_body, content_format)
    except Exception as e:
        return jsonify({'error': f'parse error: {str(e)}'}), 400

    # Store parsed config
    config_id = hashlib.md5(raw_body.encode()).hexdigest()[:12]
    redis_client.hset(f"config:{config_id}", mapping={
        'data': str(parsed),
        'format': content_format,
        'imported_at': str(time.time()),
        'source_ip': client_ip
    })

    return jsonify({'config_id': config_id, 'status': 'imported'}), 201

@app.route('/api/v2/config/<config_id>', methods=['GET'])
def get_config(config_id):
    data = redis_client.hgetall(f"config:{config_id}")
    if not data:
        return jsonify({'error': 'not found'}), 404
    return jsonify(data)

@app.route('/api/v2/config/validate', methods=['POST'])
def validate_config():
    content_format = request.args.get('format', 'yaml')
    raw_body = request.get_data(as_text=True)

    try:
        parsed = parse_config_payload(raw_body, content_format)
        return jsonify({'valid': True, 'keys': len(parsed) if isinstance(parsed, dict) else 1})
    except Exception as e:
        return jsonify({'valid': False, 'error': str(e)}), 422

@app.route('/internal/debug/redis', methods=['GET'])
def debug_redis():
    auth_header = request.headers.get('X-Internal-Token')
    if auth_header != os.environ.get('INTERNAL_DEBUG_TOKEN', 'debug-token-local'):
        return jsonify({'error': 'unauthorized'}), 401
    info = redis_client.info()
    return jsonify({'connected_clients': info.get('connected_clients'),
                    'used_memory': info.get('used_memory_human')})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', False))
